    --grad: linear-gradient(135deg, var(--pink) 0%, var(--coral) 50%, var(--orange) 100%);
    --w100: rgba(255,255,255,1); --w80: rgba(255,255,255,.8); --w70: rgba(255,255,255,.7);
    --w60: rgba(255,255,255,.6); --w50: rgba(255,255,255,.5); --w40: rgba(255,255,255,.4);
    --border: rgba(255,255,255,.08); --border-h: rgba(255,255,255,.15);
