  body{background:#000; color:var(--w60); font-family:'Inter',sans-serif; line-height:1.65;}
  .wrap{max-width:1200px; margin:0 auto; padding:0 20px;}
  h1,h2,h3{font-family:'Anton',sans-serif; font-weight:400; text-transform:uppercase; color:var(--w100); line-height:1.05;}
  a{color:inherit; text-decoration:none;}
  .label{font-size:14px; letter-spacing:.1em; text-transform:uppercase; color:var(--pink); font-weight:600;}
  .sample{font-size:12px; color:var(--w40); font-style:italic;}

  /* NAV */
  nav{display:flex; justify-content:space-between; align-items:center; padding:24px 0; border-bottom:1px solid var(--border);}
  .logo{font-family:'Anton',sans-serif; font-size:20px; letter-spacing:.02em; color:var(--w100); text-transform:uppercase;}
  .navlinks{display:flex; gap:32px; font-size:14px; color:var(--w60);}

  /* HERO */
  .hero{padding:72px 0 48px; position:relative; overflow:hidden;
    background:
      radial-gradient(ellipse 80% 50% at 50% 0%, rgba(254,49,132,.15) 0%, transparent 50%),
      radial-gradient(ellipse 60% 40% at 80% 20%, rgba(255,107,53,.1) 0%, transparent 50%), #000;}
  .badge{display:inline-flex; align-items:center; gap:8px; background:rgba(254,49,132,.1); border:1px solid rgba(254,49,132,.2); border-radius:9999px; padding:6px 16px; font-size:12px; font-weight:600; letter-spacing:.08em; text-transform:uppercase; color:var(--pink); margin-top:16px;}
  .hero h1{font-size:56px; margin:16px 0; max-width:780px;}
  .hero p.desc{font-size:18px; color:var(--w70); max-width:600px; margin-bottom:8px;}
  .attribution{font-size:14px; color:var(--w50); margin-top:8px;}

  /* BODY GRID */
  .grid{display:grid; grid-template-columns:1fr 380px; gap:48px; padding:64px 0; align-items:start;}
  .col-left section{margin-bottom:48px;}
  .col-left h2{font-size:28px; margin-bottom:16px;}
  .steps{list-style:none;}
  .steps li{display:flex; gap:16px; padding:14px 0; border-bottom:1px solid var(--border); font-size:16px; color:var(--w60);}
  .steps li span{font-family:'Anton',sans-serif; color:var(--pink); font-size:18px; min-width:28px;}
  .partner-note{background:linear-gradient(180deg,#1a1a1a 0%, #0d0d0d 100%); border:1px solid var(--border); border-radius:1rem; padding:24px; font-size:14px; color:var(--w60);}

  /* STICKY ACTIVATE CARD */
  .activate-card{position:sticky; top:24px; background:linear-gradient(180deg,#1a1a1a 0%, #0d0d0d 100%); border:1px solid var(--border); border-radius:1rem; padding:32px;}
  .activate-card h3{font-size:22px; margin-bottom:8px;}
  .activate-card .sub{font-size:14px; color:var(--w50); margin-bottom:24px;}
  .btn-primary{display:block; width:100%; text-align:center; background:var(--grad); color:#fff; border-radius:9999px; padding:16px; font-weight:600; font-size:16px; box-shadow:0 10px 40px rgba(254,49,132,.3); transition:transform .3s, box-shadow .3s; border:none; cursor:pointer;}
  .btn-primary:hover{transform:translateY(-2px); box-shadow:0 15px 50px rgba(254,49,132,.4);}
  .btn-secondary{display:block; width:100%; text-align:center; background:transparent; color:#fff; border:1px solid rgba(255,255,255,.2); border-radius:9999px; padding:14px; font-weight:600; font-size:14px; margin-top:12px; transition:background .3s, border-color .3s; cursor:pointer;}
  .btn-secondary:hover{background:rgba(255,255,255,.05); border-color:rgba(255,255,255,.4);}
  .capacity{font-size:13px; color:var(--w50); margin-top:16px; text-align:center;}

  /* MECHANISM STRIP */
  .strip{border-top:1px solid var(--border); border-bottom:1px solid var(--border); padding:32px 0;}
  .strip .wrap{display:flex; justify-content:space-between; flex-wrap:wrap; gap:16px;}
  .strip-step{flex:1; min-width:140px; text-align:center; font-size:13px; color:var(--w50); text-transform:uppercase; letter-spacing:.08em;}
  .strip-step b{display:block; color:var(--pink); font-family:'Anton',sans-serif; font-size:15px; text-transform:uppercase; margin-bottom:4px;}

  /* VERIFY NOTE */
  .verify{padding:48px 0; text-align:center;}
  .verify p{max-width:560px; margin:0 auto; font-size:15px; color:var(--w50);}

  /* RELATED ACTS */
  .related{padding:64px 0 96px;}
  .related h2{font-size:32px; margin-bottom:32px; text-align:center;}
  .cards{display:grid; grid-template-columns:repeat(3,1fr); gap:24px;}
  .card{position:relative; background:linear-gradient(180deg,#1a1a1a 0%, #0d0d0d 100%); border:1px solid var(--border); border-radius:1rem; padding:32px; overflow:hidden; transition:transform .5s, border-color .5s, box-shadow .5s;}
  .card .orb{position:absolute; top:-80px; left:-80px; width:160px; height:160px; border-radius:50%; filter:blur(60px); background:linear-gradient(135deg, rgba(254,49,132,.4), rgba(236,114,17,.3)); opacity:0; transition:opacity .7s;}
  .icon-box{width:56px; height:56px; border-radius:12px; background:rgba(254,49,132,.1); border:1px solid rgba(254,49,132,.2); display:flex; align-items:center; justify-content:center; margin-bottom:20px; transition:transform .5s, box-shadow .5s, border-color .5s;}
  .icon-box svg{width:24px; height:24px; stroke:var(--pink); stroke-width:1.5; fill:none;}
  .card h3{font-size:18px; margin-bottom:8px;}
  .card p{font-size:14px; color:var(--w50); margin-bottom:16px;}
  .card .status{font-size:12px; color:var(--pink); text-transform:uppercase; letter-spacing:.06em; margin-bottom:16px; display:block;}
  .card .bottom-accent{position:absolute; bottom:0; left:0; right:0; height:4px; background:var(--grad); transform:scaleX(0); transition:transform .5s;}
  .card:hover, .card.is-hover{transform:translateY(-8px); border-color:var(--border-h); box-shadow:0 20px 60px rgba(0,0,0,.4), 0 0 80px rgba(254,49,132,.1);}
  .card:hover .orb, .card.is-hover .orb{opacity:1;}
  .card:hover p, .card.is-hover p{color:var(--w70);}
  .card:hover .icon-box, .card.is-hover .icon-box{transform:scale(1.1); box-shadow:0 0 30px rgba(254,49,132,.3); border-color:rgba(254,49,132,.5);}
  .card:hover .bottom-accent, .card.is-hover .bottom-accent{transform:scaleX(1);}
  .view-link{font-size:13px; font-weight:600; color:var(--pink);}

  footer{border-top:1px solid var(--border); padding:40px 0; display:flex; justify-content:space-between; align-items:center; font-size:13px; color:var(--w40);}

  /* MOBILE */
  @media (max-width:768px){
    .hero h1{font-size:36px;}
    .grid{grid-template-columns:1fr; padding-bottom:100px;}
    .activate-card{position:fixed; bottom:0; left:0; right:0; top:auto; border-radius:0; border-left:none; border-right:none; border-bottom:none; z-index:50; padding:20px;}
    .activate-card .sub, .capacity{display:none;}
    .btn-secondary{display:none;}
    .strip .wrap{flex-direction:column; text-align:left;}
    .cards{grid-template-columns:1fr;}
    footer{flex-direction:column; gap:8px; text-align:center;}
    nav .navlinks{display:none;}
  }
</style>
</head>
<body>

<div class="wrap">
  <nav>
    <div class="logo">Gratitude</div>
    <div class="navlinks"><a href="#">Acts</a><a href="#">Fund</a><a href="#">How it works</a></div>
  </nav>
</div>

<section class="hero">
  <div class="wrap">
    <div class="label">Community Meals</div>
    <div class="badge">Funded and ready</div>
    <h1>Provide a week of school meals</h1>
    <p class="desc">Give a family the food they need to get through a full week, delivered through a trusted local partner.</p>
    <p class="attribution">Made possible by [NEEDS INPUT: Sponsor name]</p>
    <p class="sample">Sample content. Act name, sponsor, and partner shown here are fictional for design purposes.</p>
  </div>
</section>

<div class="wrap">
  <div class="grid">
    <div class="col-left">
      <section>
        <h2>About this act</h2>
        <p>This act provides seven days of groceries to a family identified by our nonprofit partner. The capacity for this act is already funded, so when you activate it, delivery begins right away. No payment is required from you.</p>
      </section>

      <section>
        <h2>What happens after you activate</h2>
        <ul class="steps">
          <li><span>01</span>Your activation gives the go-ahead. The act moves from ready to in motion.</li>
          <li><span>02</span>Our nonprofit partner delivers the meals directly to the family.</li>
          <li><span>03</span>Delivery is verified, not assumed.</li>
          <li><span>04</span>You see what happened and how your choice became real.</li>
        </ul>
      </section>

      <section>
        <h2>Delivered by</h2>
        <div class="partner-note">
          <strong style="color:var(--w80);">[NEEDS INPUT: Nonprofit partner name]</strong><br>
          A trusted partner responsible for delivery and on-the-ground verification. Partner details are sample content for this wireframe.
        </div>
      </section>
    </div>

    <div class="col-right">
      <div class="activate-card">
        <h3>Ready when you are</h3>
        <p class="sub">It's funded. Your choice gives the go-ahead. It costs you nothing right now.</p>
        <button class="btn-primary">Activate this act</button>
        <button class="btn-secondary">Fund more acts like this</button>
        <p class="capacity">[NEEDS INPUT: number] acts of this kind funded and ready</p>
      </div>
    </div>
  </div>
</div>

<section class="strip">
  <div class="wrap">
    <div class="strip-step"><b>Pre-fund</b>Capacity committed</div>
    <div class="strip-step"><b>Activate</b>You give the go-ahead</div>
    <div class="strip-step"><b>Deliver</b>Partner takes action</div>
    <div class="strip-step"><b>Verify</b>Delivery confirmed</div>
    <div class="strip-step"><b>Show Impact</b>You see what happened</div>
  </div>
</section>

<section class="verify">
  <div class="wrap">
    <p>Verification protects the privacy and dignity of everyone involved. You'll see confirmation that this act was delivered, not a photo of the person who received it.</p>
  </div>
</section>

<section class="related">
  <div class="wrap">
    <h2>More acts ready now</h2>
    <div class="cards">
      <div class="card">
        <div class="orb"></div>
        <div class="icon-box"><svg viewBox="0 0 24 24"><path d="M4 12h16M4 6h16M4 18h16"/></svg></div>
        <span class="status">Funded and ready</span>
        <h3>[NEEDS INPUT: Act name]</h3>
        <p>Short one-line description of the act goes here.</p>
        <div class="bottom-accent"></div>
        <a class="view-link" href="#">View act →</a>
      </div>
      <div class="card is-hover">
        <div class="orb"></div>
        <div class="icon-box"><svg viewBox="0 0 24 24"><path d="M12 2l3 7h7l-5.5 4.5L18 21l-6-4-6 4 1.5-7.5L2 9h7z"/></svg></div>
        <span class="status">Funded and ready</span>
        <h3>[NEEDS INPUT: Act name]</h3>
        <p>Shown here in its hover state for reference.</p>
        <div class="bottom-accent"></div>
        <a class="view-link" href="#">View act →</a>
      </div>
      <div class="card">
        <div class="orb"></div>
        <div class="icon-box"><svg viewBox="0 0 24 24"><path d="M12 21s-8-4.5-8-11a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 6.5-8 11-8 11z"/></svg></div>
        <span class="status">Funded and ready</span>
        <h3>[NEEDS INPUT: Act name]</h3>
        <p>Short one-line description of the act goes here.</p>
        <div class="bottom-accent"></div>
        <a class="view-link" href="#">View act →</a>
      </div>
    </div>
  </div>
</section>

<div class="wrap">
  <footer>
    <div>© Gratitude.com</div>
    <div>Gratitude, delivered.</div>
  </footer>
</div>

</body>
</html>
